//! Raw FFI bindings to ggml, qwentts.cpp (`qwen.h`) and qwen3-asr.cpp (`qwen3_asr_c.h`),
//! all built against ONE static ggml from our llama.cpp fork. Generated by bindgen in
//! build.rs; the safe wrappers live in the `lectover` crate.

// The names are the C API's own (`ggml_backend_t`, `GGML_TYPE_F32`); they cannot follow Rust
// naming.
#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
